            BackColor=Color.FromArgb(12,25,36);ForeColor=Color.WhiteSmoke;Font=SystemFonts.MessageBoxFont;AutoScaleMode=AutoScaleMode.Dpi;ClientSize=new Size(1100,840);MinimumSize=SizeFromClientSize(new Size(800,580));StartPosition=FormStartPosition.CenterParent;KeyPreview=true;
