            var choices=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill,WrapContents=true};preset.Name="mixedNavigationPreset";preset.DropDownStyle=ComboBoxStyle.DropDownList;preset.Width=440;foreach(string name in PresetNames)preset.Items.Add(name);preset.SelectedIndex=0;choices.Controls.Add(preset);Configure(load,"mixedNavigationLoad","Load selected copy");Configure(reset,"mixedNavigationReset","Reset applied copy");choices.Controls.Add(load);choices.Controls.Add(reset);content.Controls.Add(choices);
