            details.Name="mixedNavigationDetails";details.ReadOnly=true;details.Multiline=true;details.WordWrap=true;details.ScrollBars=ScrollBars.Vertical;details.Dock=DockStyle.Fill;details.MinimumSize=new Size(730,175);details.Height=175;details.BackColor=Color.FromArgb(9,20,30);details.ForeColor=ForeColor;details.Font=mono;content.Controls.Add(details);
            var footer=new Panel{Dock=DockStyle.Fill,Margin=Padding.Empty,Padding=new Padding(12,6,12,6)};var close=new Button{Dock=DockStyle.Right,Width=130,DialogResult=DialogResult.Cancel};Configure(close,"mixedNavigationClose","Close");close.Click+=delegate{Close();};footer.Controls.Add(close);root.Controls.Add(footer,0,1);CancelButton=close;
            load.Click+=delegate{LoadCopy(preset.SelectedIndex);};reset.Click+=delegate{LoadCopy(state.Preset);};one.Click+=delegate{Advance(false);};all.Click+=delegate{Advance(true);};preset.SelectedIndexChanged+=delegate{Sync();};KeyUp+=delegate(object sender,KeyEventArgs e){held.Remove(e.KeyCode);};Activated+=delegate{SampleHeld();};Deactivate+=delegate{SampleHeld();};LoadCopy(0);
