        static void Configure(Button b,string name,string text){b.Name=name;b.Text=text;b.AutoSize=true;b.MinimumSize=new Size(140,34);b.Padding=new Padding(7,2,7,2);b.UseVisualStyleBackColor=false;b.BackColor=Color.FromArgb(29,56,72);b.ForeColor=Color.WhiteSmoke;b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderColor=Color.FromArgb(100,130,150);b.EnabledChanged+=delegate{if(b.IsDisposed||b.Disposing)return;b.BackColor=b.Enabled?Color.FromArgb(29,56,72):Color.LightGray;b.ForeColor=b.Enabled?Color.WhiteSmoke:Color.Black;};}
        void LoadCopy(int index){state=clocked?(IPracticeMixedComparison)PracticeMixedClockState.Create(programs,startup,index):moving?(IPracticeMixedComparison)PracticeMixedMovementState.Create(programs,startup,index):PracticeMixedNavigationState.Create(programs,startup,index);feedback.Text=clocked?"Prepared clock copy; no automatic updates. Choose 1 source frame.":moving?"Prepared moving copy; no automatic updates. Choose 1 copied poll.":"Prepared independent copy; no automatic updates. Choose 1 copied visit.";Sync();}
        void Advance(bool remaining,int limit=int.MaxValue){if(IsDisposed||Disposing||state==null||!state.CanAdvance)return;try{do{state=state.AdvanceForStudy();}while(remaining&&state.CanAdvance&&state.Visits<limit);feedback.Text=state.CanAdvance?state.NavigationDescription+"; copied visit complete.":(state.WindowVisits+" compared updates complete. Reset the applied copy to repeat.");Sync();}catch(NotSupportedException e){feedback.Text="Copy preserved: "+e.Message;}}
        static int I(byte[] b,int at){return BitConverter.ToInt32(b,at);}static int W(byte[] b,int at){return BitConverter.ToInt16(b,at);}
        void Sync()
        {
            if(IsDisposed||Disposing||state==null)return;var f=state.CopyFleetPool();int child=state.AircraftFleet;var task=state.Backing.CopyTaskRecord(child);bool pending=preset.SelectedIndex!=state.Preset;
            summary.Text="Applied: "+PresetNames[state.Preset]+"\r\n"+(clocked?"Frames ":moving?"Polls ":"Visits ")+state.Visits+" / "+state.WindowVisits+"   |   Parent "+state.ParentFleet+" → aircraft "+child+"   |   "+(I(f,child*492)==6?"Stored aircraft":"Active aircraft")+"   |   Timer "+I(task,252)+"   |   Patrol phase "+I(task,200)+"\r\nActivations "+state.TotalActivations+"   |   Selected waypoint "+state.SelectedWaypoint+(pending?"   |   Pending choice requires Load":"");
            one.Enabled=all.Enabled=state.CanAdvance;if(boundary!=null){boundary.Enabled=(clocked||state.Preset==6)&&state.Visits<BoundaryLimit;if(clocked)boundary.Text=state.Preset==6?"To frame 67 (zero reset)":state.Preset<3?(state.Visits<31?"To frame 31 (phase 30 held)":"To frame 35 (phase 32 resume)"):(state.Visits<35?"To frame 35 (phase 32 held)":"To frame 36 (resume)");}if(clocked){SyncClockDetails();canvas.Invalidate();return;}var text=new StringBuilder();text.AppendLine(moving?"Last copied callback sequence: policy/navigation, then two movement batches.":"Last copied callback sequence: ship and aircraft positions stay fixed here.");
            if(state.Visits==0)text.AppendLine(moving?"No measured poll yet. Ship and aircraft positions update only when the source scheduler visits their slots.":"No measured visit yet. Four profiles have a prepared navigation start; two begin before it.");else{text.AppendLine("Caller word supplied: 0 → before parent: "+state.CounterBeforeParent+" → after parent: "+state.CounterAfterParent+" → after all callbacks: "+state.CallerWordAfter);text.AppendLine("Initial collision-kind writes this visit: "+state.InitialCollisionAliasWrites+"; navigation: "+state.NavigationDescription+"; UI refresh requests: "+state.UiRequests+".");}
            text.AppendLine("Blocked-destination activation starts a different aircraft patrol leg from the route-start activation. A later aircraft callback makes the final caller word 6 in both cases; that final value alone hides the difference.");
            text.AppendLine(moving?"Each poll supplies phase 1, clock 12345 + 40 × poll, delta 40 and caller word 0, then two movement batches. Seven 96-poll profiles match complete original states; this does not establish natural application pacing.":"Each click supplies phase 1, clock 12345 + 40 × visit, delta 40 and caller word 0. The original caller's natural values remain unknown. All six profiles match complete original capture states for eight visits.");
            text.AppendLine("Schematic copied map: gold = ship 16 and first queued point; blue = parent carrier; cyan = aircraft and its patrol point; red = supplied blocker. Axes are original world X right / Y down, 0..630. Overlapping aircraft/carrier markers share a source position.");
            text.AppendLine(moving?"Motion and resource updates use recovered scheduler bodies with supplied diagnostic map columns. The short route clears selected fleet 249's shared flag at poll 64. No automatic clock, movies, audio, network, owner AI or complete battle runs. Reset/Load replace only this copy.":"This study updates policy and navigation only. No ship movement, aircraft flight, automatic clock, movies, audio, network or complete battle runs. Reset and Load replace only this study's copy.");details.Text=text.ToString();canvas.Invalidate();
        }
        void SyncClockDetails()
        {
            var c=ClockStudyState;var text=new StringBuilder();text.AppendLine("Clock field (ms): BEFORE / BODY / AFTER");
            text.AppendLine("Previous: "+c.BeforeClock.PreviousMilliseconds+" / "+c.BodyClock.PreviousMilliseconds+" / "+c.Clock.PreviousMilliseconds);
            text.AppendLine("Current: "+c.BeforeClock.CurrentMilliseconds+" / "+c.BodyClock.CurrentMilliseconds+" / "+c.Clock.CurrentMilliseconds);
            text.AppendLine("Game: "+c.BeforeClock.GameMilliseconds+" / "+c.BodyClock.GameMilliseconds+" / "+c.Clock.GameMilliseconds);
            text.AppendLine("Delta: "+c.BeforeClock.DeltaMilliseconds+" / "+c.BodyClock.DeltaMilliseconds+" / "+c.Clock.DeltaMilliseconds);
            text.AppendLine("Phase: "+c.BeforePhase+" -> "+c.Phase.Value+"    Pause WORD: "+c.PauseWord);
            text.AppendLine("Driver: "+(c.Visits==0?"not called yet":c.SimulationAdvanced?"advanced":"held")+"; total "+c.DriverVisits+"; held frames "+c.HeldFrames+"; neutral passes "+c.NeutralPasses);
            text.AppendLine("Sample: "+c.SampleMilliseconds+"; contact 249: "+c.CopyFleetPool()[249*492+480]+"; selected task flag: "+c.SelectedFleetFlag);clockReadout.Text=text.ToString();
            text.Clear();text.AppendLine("The header samples time before the body. The body sees the PRECEDING delta; the next delta is computed only after the simulation slice.");
            text.AppendLine("Pause words and samples are supplied comparison inputs. Phase starts at 0 and increments only with pause WORD 0. Nonzero pause holds policy, navigation and both movement batches while the clock header continues. Holding phase 32 does not repeat its neutral pass.");
            if(c.Visits!=0){if(c.SimulationAdvanced)text.AppendLine("Last driver: before parent "+c.CounterBeforeParent+"; after parent "+c.CounterAfterParent+"; after prephase "+c.PrephaseCallerWordAfter+"; returned scratch 0x"+c.DriverScratchAfter.ToString("X8")+". An aligned neutral pass reuses the supplied incoming frame word.");else text.AppendLine("Last frame held the simulation slice. No driver was called and no new callback scratch is claimed.");}
            text.AppendLine("Short-route input: frame 67 repeats a sample and resets current/game/delta to 1 after the body. Frame 68 sees delta 1, then produces delta 15024. Frame 69 sees 15024 and activates aircraft 27. Applying the new delta immediately activates it one frame too early.");
            text.AppendLine("Gold is ship 16; blue is the parent carrier; cyan is its aircraft; dashed lines are queued points. The copied scheduler determines which fleet moves. The selected-fleet flag clear is delayed to frame 67 by three held frames.");
            text.AppendLine("Complete original comparisons support seven 96-frame histories. This view does not run the original wait/render/input loop, pause-deadline compensation, natural caller values, active owner AI, combat, audio, networking or a complete Practice battle. Reset/Load affect only this copy.");details.Text=text.ToString();
        }
        void PaintCopy(object sender,PaintEventArgs e)
        {
            if(IsDisposed||Disposing||state==null)return;var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;var f=state.CopyFleetPool();int child=state.AircraftFleet,parent=state.ParentFleet;const int left=36,top=25,side=280;
            Func<int,int,PointF> point=delegate(int x,int y){return new PointF(left+x*side/630f,top+y*side/630f);};
            using(var sea=new SolidBrush(Color.FromArgb(17,43,59)))g.FillRectangle(sea,left,top,side,side);
            using(var grid=new Pen(Color.FromArgb(39,70,85)))for(int n=0;n<=7;n++){float d=n*40;g.DrawLine(grid,left+d,top,left+d,top+side);g.DrawLine(grid,left,top+d,left+side,top+d);}
            using(var brush=new SolidBrush(ForeColor))for(int n=0;n<=4;n++){int value=n==4?630:n*160;var p=point(value,value);g.DrawString(value.ToString(),Font,brush,p.X-8,top+side+5);g.DrawString(value.ToString(),Font,brush,left-32,p.Y-7);}
            Action<int,Color,bool> marker=delegate(int slot,Color color,bool ring){var p=point(W(f,slot*492+12),W(f,slot*492+14));using(var pen=new Pen(color,2)){if(ring)g.DrawEllipse(pen,p.X-7,p.Y-7,14,14);else g.DrawRectangle(pen,p.X-4,p.Y-4,8,8);}};
            Action<int,Color> route=delegate(int slot,Color color){int x=W(f,slot*492+40),y=W(f,slot*492+50);if(x<0||x>630||y<0||y>630)return;var a=point(W(f,slot*492+12),W(f,slot*492+14));var b=point(x,y);using(var pen=new Pen(color,2)){pen.DashStyle=DashStyle.Dash;g.DrawLine(pen,a,b);g.DrawRectangle(pen,b.X-3,b.Y-3,6,6);}};
            route(16,Color.Gold);if(I(f,child*492)==3)route(child,Color.Cyan);marker(parent,Color.CornflowerBlue,true);marker(child,Color.Cyan,false);marker(16,Color.Gold,false);if(I(f,30*492)==11)marker(30,Color.Tomato,true);
            var terrain=state.CopyTerrainPool();if(I(terrain,0)==1){var p=point(W(terrain,12),W(terrain,14));using(var pen=new Pen(Color.Tomato,2)){g.DrawLine(pen,p.X-5,p.Y-5,p.X+5,p.Y+5);g.DrawLine(pen,p.X-5,p.Y+5,p.X+5,p.Y-5);}}
            int textLeft=350;var task=state.Backing.CopyTaskRecord(child);string info="Gold ship 16: "+W(f,16*492+12)+", "+W(f,16*492+14)+"\r\nFirst ship point: "+W(f,16*492+40)+", "+W(f,16*492+50)+"\r\nNavigation: "+state.NavigationDescription+"\r\n\r\nBlue parent "+parent+": "+W(f,parent*492+12)+", "+W(f,parent*492+14)+"\r\nCyan aircraft "+child+": "+(I(f,child*492)==6?"stored":"active")+"\r\nAircraft patrol point: "+W(f,child*492+40)+", "+W(f,child*492+50)+"\r\nPatrol phase: "+I(task,200)+(moving?"\r\n\r\nNext scheduler slot: "+MovingSnapshot.Schedule.BatchStart+"; cycles: "+MovingSnapshot.Schedule.CompletedCycles+"\r\nMoving ship visits: "+MovingSnapshot.TotalShipMoves+"; air: "+MovingSnapshot.TotalAircraftMoves+"\r\nSelected 249 flag: "+MovingSnapshot.SelectedFleetFlag+"\r\nDashed lines show queued points.":"\r\n\r\nThis view does not move either fleet.\r\nDashed lines show queued points.");
            using(var brush=new SolidBrush(ForeColor))g.DrawString(info,mono,brush,new RectangleF(textLeft,25,Math.Max(320,canvas.ClientSize.Width-textLeft-12),310));
        }
        void SampleHeld(){if(IsDisposed||Disposing)return;foreach(Keys key in new[]{Keys.Enter,Keys.Space,Keys.Escape}){if((GetAsyncKeyState((int)key)&0x8000)!=0)held.Add(key);else held.Remove(key);}}
        bool GateKey(Keys key){if(IsDisposed||Disposing)return true;if(key!=Keys.Enter&&key!=Keys.Space&&key!=Keys.Escape)return false;var button=ActiveControl as Button;if(key!=Keys.Escape&&button==null)return false;if(held.Add(key)){if(key==Keys.Escape)Close();else if(button.Enabled)button.PerformClick();}return true;}
        protected override void OnKeyDown(KeyEventArgs e){if(e.Modifiers==Keys.None&&GateKey(e.KeyCode)){e.Handled=e.SuppressKeyPress=true;return;}base.OnKeyDown(e);}
        protected override bool ProcessDialogKey(Keys data){if((data&Keys.Modifiers)==Keys.None&&GateKey(data&Keys.KeyCode))return true;return base.ProcessDialogKey(data);}
        protected override void Dispose(bool disposing){if(disposing)mono.Dispose();base.Dispose(disposing);}
    }
